// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(amount > 0);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool deposited, ) = address(c).call{value: amount}("");
        require(deposited, "Deposit failed");

        uint256 balanceBefore = c.balances(actor);
        assertEq(balanceBefore, amount, "Balance not credited");

        vm.prank(actor);
        c.withdraw();

        uint256 balanceAfter = c.balances(actor);
        assertTrue(balanceAfter == 0, "Balance should be zero after withdraw");
    }
}
